import sys, re, random; sys.path.insert(0,'.'); import h
F=h.R+'data/papers_test/md_agents/Benson 1985 Cunninghamia_primary juvenile period.md'
stem='Benson 1985 Cunninghamia_primary juvenile period'
txt=open(F,encoding='utf-8').read()
def table(after, ncol):
    seg=txt.split(after,1)[1]; rows=[]
    for line in seg.splitlines():
        if line.startswith('| ') and not line.startswith('|---'): rows.append([c.strip() for c in line.strip().strip('|').split('|')])
        elif rows and not line.startswith('|'): break
    return rows[1:]
t1=table('TABLE 1',4); t2=table('TABLE 2',8)
# expand abbreviated genera
def expand(rows,i):
    g=None
    for r in rows:
        m=re.match(r'([A-Z])\. (.+)',r[i])
        if m: r[i]=g+' '+m.group(2)
        else: g=r[i].split()[0]
expand(t1,1); expand(t2,0)
fam={r[1]:(r[0].capitalize(),r[2]) for r in t1}
src='Benson, D. H. (1985). Maturation periods for fire-sensitive shrub species in Hawkesbury Sandstone vegetation. Cunninghamia, 1(3), 339-349.'
codes={'fs':'obligate','r':'resprouter','fs*':'obligate'}
paperwide=("fire response codes (Table 1, p. 341): 'fs' = fire-sensitive, 'r' = resprouter, '?' = probably fire-sensitive; "
 "Age at first flower production from seed_repr3 = number of years to first flowering after fire of marked seedlings (Table 2, p. 342); "
 "Time to 50% flowering = years to reach at least 50 per cent of individuals flowering, given in brackets in Table 2 where 10 or more individuals were marked at one site")
sites={'A':1,'B':2,'C':3,'D':4}
bw=dict(Latitude='-33.5',Longitude='151.25',Rainfall_mm='1250',Fire_season_categorical='Summer',Fire_severity_categorical='hot')
bwnote="Brisbane Water National Park (33° 30'S, 151° 15'E), all four sites within about 0.5 km of each other; Rainfall_mm printed as 'about 1250 mm per annum'; fire: hot summer (1974-75) fire; Fire_severity_categorical 'hot' as printed (abstract: seedlings established after hot fires)"
gl=dict(Latitude='-33.5833',Longitude='151',Rainfall_mm='930',Fire_season_categorical='Summer',Fire_severity_categorical='hot')
glnote="Glenorie (33° 35'S, 151° 00'E), average rainfall 930 mm per annum; fire: burnt January 1975, Fire_season_categorical derived from fire date January 1975; Fire_severity_categorical 'hot' as printed (abstract: seedlings established after hot fires)"
rows=[]
def base(name):
    g,s=name.split(' ',1); f,c=fam[name]
    d=dict(Genus=g,Species=s,scientific_name=name,Family=f,Source=src,File_name=stem)
    if c in codes: d['fire_response categorical_surv1']=codes[c]
    else: d['fire_response categorical_surv1']=c
    n=[]
    if c=='fs*': n.append("fire_response categorical_surv1 printed as 'fs*'; footnote: Beadle (1940) states Petrophile pulchella has a lignotuber and 92 per cent survival after fire, not the case at the study sites according to the author")
    if name=='Poranthera ericifolia': n.append("Results text (p. 342) names 'Poranthera microphylla' as flowering after one year; Table 2 and Table 1 name Poranthera ericifolia")
    return d,n
def val(v):
    m=re.match(r'^\*?(\d+)(?:\((\d+)\))?$',v)
    return m.group(1),m.group(2)
for r in t2:
    name=r[0]
    for k,i in sites.items():
        v=r[i]
        if not v: continue
        d,n=base(name); d.update(bw); d['Location_name']='Site '+k
        if v=='no flowering yet':
            d['Age at first flower production from seed_repr3']='>8'
            n.append("Age at first flower production from seed_repr3: printed as 'no flowering yet'; '>8' from the eight-year recording period (Table 3 time axis ends at 8 years after fire)")
        else:
            a,b=val(v); d['Age at first flower production from seed_repr3']=a
            if b: d['Time to 50% flowering']=b; d['Time_unit']='years'
            if v.startswith('*'): n.append("value printed as '%s'; '*' marks the footnote on bracketed values"%v)
        if r[5]: n.append("Brisbane Water Vicinity value %s years (first flowering of plants within about 30 m of the transects, many unaffected or only slightly affected by the fire; not marked seedlings)"%r[5])
        rows.append((d,['Table 2, p. 342']+n+[bwnote,paperwide]))
    if r[6]:
        d,n=base(name); d.update(gl)
        a,b=val(r[6]); d['Age at first flower production from seed_repr3']=a
        if b: d['Time to 50% flowering']=b; d['Time_unit']='years'
        if r[7]: n.append("Glenorie Vicinity value %s years (first flowering of plants within about 30 m of the transect, many unaffected or only slightly affected by the fire; not marked seedlings)"%r[7])
        rows.append((d,['Table 2, p. 342']+n+[glnote,paperwide]))
# 1980 low-intensity fire at site A
d,n=base('Platysace linearifolia'); d.update(Latitude='-33.5',Longitude='151.25',Rainfall_mm='1250',Location_name='Site A',Fire_season_categorical='Winter',Fire_severity_categorical='Low')
d['fire_response categorical_surv1']='resprouter'
rows.append((d,['text, p. 345',"separate fire: July-August 1980 low-intensity fire burnt half of the site A transect, no canopy scorch (p. 340); individuals that had appeared only as seedlings after the 1974-75 fire were not killed but resprouted at ground level; resprouter_type not stated; Fire_season_categorical derived from fire date July-August 1980; Fire_severity_categorical from 'low-intensity fire' with no canopy scorch","Brisbane Water National Park (33° 30'S, 151° 15'E); Rainfall_mm printed as 'about 1250 mm per annum'",paperwide]))
for d,n in rows: d['Notes']='; '.join(n)
for d,n in random.sample(rows,3):
    print({k:d.get(k) for k in ['scientific_name','Location_name','Latitude','Age at first flower production from seed_repr3','Time to 50% flowering','fire_response categorical_surv1','Family']})
    print('   SRC:',[l for l in txt.splitlines() if '| '+d['scientific_name'] in l or ('| '+d['Genus'][0]+'. '+d['Species']) in l])
if sys.argv[1:]==['write']: print('written',h.add([d for d,n in rows]))
else: print(len(rows))
