cd /tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/031a3a3c-5daf-4463-a439-3e0a2e9af806/scratchpad; cat > knox.py <<'EOF'
import sys, re, random; sys.path.insert(0,'.'); import h
stem='Knox & Clarke 2004 Cunninghamia_primary juvenile period'
txt=open(h.R+'data/papers_test/md_agents/'+stem+'.md',encoding='utf-8').read()
def table(after):
    seg=txt.split(after,1)[1]; rows=[]
    for line in seg.splitlines():
        if line.startswith('| ') and not line.startswith('|---'): rows.append([c.strip() for c in line.strip().strip('|').split('|')])
        elif rows and not line.startswith('|'): break
    return rows[1:]
t1={r[0]:r for r in table('**Table 1.')}; t2=table('**Table 2.')
order=list(t1)+[r[0] for r in t2 if r[0] not in t1]
t2={r[0]:r for r in t2}
src='Knox, K. J. E., & Clarke, P. J. (2004). Fire response syndromes of shrubs in grassy woodlands in the New England Tableland Bioregion. Cunninghamia, 8(3), 348-353.'
def parse_name(n):
    plain=n.replace('*','')
    m=re.match(r'(\S+) (.+?)(?: ((?:subsp|var)\. .+))?$',plain)
    return m.group(1),m.group(2),m.group(3) or ''
def tv(v):
    if v in ('\\*','n.a.',''): return ''
    m=re.match(r'Not flowering after ([\d.]+) years',v)
    if m: return '>'+m.group(1)
    m=re.match(r'([<>]?) ?([\d.]+) years',v)
    return m.group(1)+m.group(2)
fr={'resprouter':'resprouter','obligate seeder':'obligate'}
paperwide=("fire response classes (p. 349): obligate seeder = less than 30% of individuals survived 100% leaf scorch, resprouter = more than 70% survived (Gill & Bradstock 1992); "
 "values pooled across both reserves, not split by site; sites: Imbota Nature Reserve (10 km SE of Armidale, average yearly rainfall 790 mm, experimental burns in Spring 1999) and Booroolong Nature Reserve (30 km NW of Armidale, average yearly rainfall 884 mm at nearby Guyra, experimental burns in Autumn 2000); "
 "fire intensity not measured; moderate intensity and low intensity fires expected in high fuel load and low fuel load areas respectively (p. 349); "
 "juvenile periods observed in August 2002 and September 2003 at burn sites 1.5 to 3 years post-fire in 2002 (p. 350)")
rows=[]
for n in order:
    g,s,ss=parse_name(n)
    d=dict(Genus=g,Species=s,subsp=ss,scientific_name=g+' '+s,Source=src,File_name=stem,
           Location_name='Imbota Nature Reserve; Booroolong Nature Reserve',Fire_type='experimental burn',Fire_season_categorical='Autumn; Spring')
    notes=[]; locs=[]
    r1=t1.get(n); r2=t2.get(n)
    if r1:
        locs.append('Table 1, p. 350')
        d['fire_response categorical_surv1']=fr[r1[1]]
        if r1[4]!='n.a.': d['resprouter_type']=r1[4].replace('/','; ')
        notes.append('survival %s%% (sample size %s)'%(r1[2],r1[3].strip('()')))
    if r2:
        locs.append('Table 2, p. 351')
        if not r1: d['fire_response categorical_surv1']=fr[r2[1]]
        d['primary_juvenile_period']=tv(r2[2]); d['secondary_juvenile_period']=tv(r2[3])
        if d['secondary_juvenile_period']: d['Time_unit']='years'
        for col,v in (('primary_juvenile_period',r2[2]),('secondary_juvenile_period',r2[3])):
            if v.startswith('Not flowering'): notes.append("%s printed as '%s'"%(col,v))
    if r1 and r1[4]!='n.a.': notes.append("resprouter_type printed as '%s'"%r1[4])
    if not r1: notes.append('not listed in Table 1; fire response from Table 2')
    if n.startswith('*Indigofera australis'): notes.append("primary_juvenile_period: Discussion (p. 352) says it appears to be more than four years in the current study; Table 2 and Results give 4 years")
    if 'setulosai' in n: notes.append("Species as printed 'setulosai'")
    d['Notes']='; '.join([', '.join(locs)]+notes+[paperwide])
    rows.append((d,n))
for d,n in random.sample(rows,3):
    print({k:d[k] for k in d if k not in('Notes','Source','File_name','Location_name')}); print('  T1',t1.get(n)); print('  T2',t2.get(n))
if sys.argv[1:]==['write']: print('written',h.add([d for d,n in rows]))
else: print(len(rows))
