        col='Time to first flower production resprout_repr3a'
        sd,sn=shared; del sd[col]
        for d,notes in res:
            site='NL' if d.get('Location_name')==NL else 'LCR'
            if n in T:
                w,txt=T[n][0] if site=='NL' else T[n][1]
                d[col]=fmt(w/52); notes+=["%s converted from %d weeks; Appendix 1 first flowering resprouts printed as '%s'; text (p. 137) gives flowering %s weeks after the fires in the %s area"%(col,w,c[6],txt,'Narrabeen Lagoon' if site=='NL' else 'Lane Cove River')]
            elif site=='NL':
                d[col]=fmt(17/52); notes+=["%s converted from 17 weeks; Appendix 1 first flowering resprouts printed as '17w,31+w'; text (p. 138): one plant in the Narrabeen Lagoon area flowering 17 weeks (May 1994) after the fires"%col]
        if n=='Leptospermum trinervium':
            sn+=["first flowering resprouts '31+w' in Appendix 1 not assigned to a site (Notes only)"]
            sn[:]=[x for x in sn if not x.startswith(col)]
        else:
            sn[:]=[x for x in sn if not x.startswith(col)]
        has=[k for k in ('Age at first flower production from seed_repr3','primary_juvenile_period','secondary_juvenile_period') if sd.get(k)]
        return res+([(sd,sn)] if has else []), (None if has else sn)
    return rowsout,None
